For a feasible instance return {"status":"optimal","assignment":{job:machine,...},"objective":integer,"checks":{"loads":{every_machine:integer,...},"opened":[machine,...],"variable_cost":integer,"fixed_cost":integer},"explanation":"short explanation"}.
